import './profile.scss';
import { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Profile = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  console.log('Profile: profile id=', id);
  console.log('Profile: token=', sessionStorage.getItem('token'));

  const fetchUser = async () => {
    const token = sessionStorage.getItem('token');
    if (!token) {
      console.log('Profile: No token found in sessionStorage');
      setError('No authentication token found. Please log in.');
      setLoading(false);
      navigate('/login');
      return;
    }

    if (!id || !/^[0-9a-fA-F]{24}$/.test(id)) {
      console.log('Profile: Invalid user ID format:', id);
      setError('Invalid profile ID format. Please check the URL.');
      setLoading(false);
      return;
    }

    try {
      console.log(`Profile: Sending GET request to http://localhost:5000/api/users/${id}`);
      console.log(`Profile: Authorization header: Bearer ${token}`);
      const res = await axios.get(`http://localhost:5000/api/users/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Profile: Fetch user response=', {
        status: res.status,
        data: JSON.stringify(res.data, null, 2),
        headers: JSON.stringify(res.headers, null, 2),
      });
      if (!res.data || !res.data._id) {
        console.log('Profile: No valid user data returned');
        setError('No user data found for this ID.');
        setUser(null);
      } else {
        console.log('Profile: Setting user=', {
          _id: res.data._id,
          username: res.data.username,
          name: res.data.name,
          email: res.data.email,
        });
        setUser(res.data);
        setError(null);
      }
    } catch (err) {
      console.error('Profile: Error fetching user:', err.message);
      console.error('Profile: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
        headers: JSON.stringify(err.response?.headers, null, 2),
      });
      let errorMessage = 'Failed to load profile.';
      if (err.response) {
        switch (err.response.status) {
          case 400:
            errorMessage = 'Invalid user ID. Please check the URL.';
            break;
          case 401:
            errorMessage = 'Session expired. Please log in again.';
            sessionStorage.removeItem('token');
            sessionStorage.removeItem('user');
            navigate('/login');
            break;
          case 404:
            errorMessage = 'User not found.';
            break;
          case 500:
            errorMessage = 'Server error. Please try again later.';
            break;
          default:
            errorMessage = err.response.data?.message || 'Failed to load profile.';
        }
      } else {
        errorMessage = `Network error: ${err.message}`;
      }
      setError(errorMessage);
      setUser(null);
    } finally {
      setLoading(false);
      console.log('Profile: fetchUser completed, loading=', false);
    }
  };

  useEffect(() => {
    console.log('Profile: useEffect triggered');
    setLoading(true);
    fetchUser();
  }, [id, navigate]);

  if (loading) {
    return <div className="profile">Loading profile...</div>;
  }

  if (error) {
    return (
      <div className="profile error">
        <p>{error}</p>
        <button onClick={() => { setError(null); setLoading(true); fetchUser(); }}>
          Retry
        </button>
        <button onClick={() => navigate('/login')}>
          Log In
        </button>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="profile">
        <p>User not found.</p>
        <button onClick={() => { setError(null); setLoading(true); fetchUser(); }}>
          Retry
        </button>
      </div>
    );
  }

  console.log('Profile: user=', JSON.stringify(user, null, 2));

  return (
    <div className="profile">
      <div className="profile-details">
        <img
          src={user.profilePicture || '/default-avatar.png'}
          alt={`${user.username}'s profile`}
          className="avatar"
          onError={(e) => {
            console.error(`Profile: Image load error for ${user.username}:`, e);
            e.target.src = '/default-avatar.png';
          }}
        />
        <div className="info">
          <h2>{user.username || 'No username'}</h2>
          <p>
            <strong>Name:</strong> {user.name || 'No name provided'}
          </p>
          <p>
            <strong>Email:</strong> {user.email || 'No email provided'}
          </p>
          <p>
            <strong>Bio:</strong> {user.bio || 'No bio provided'}
          </p>
          <p>
            <strong>Born:</strong>{' '}
            {user.dob
              ? new Date(user.dob).toLocaleDateString()
              : 'No date of birth provided'}
          </p>
        </div>
      </div>
    </div>
  );
};

export default Profile;
